def md(s): return {'cell_type':'markdown','metadata':{},'source':s.splitlines(True)}
def code(s): return {'cell_type':'code','execution_count':None,'metadata':{},'outputs':[],'source':s.splitlines(True)}
def sections(t):
 hs=list(re.finditer(r'^#{1,3} .+$',t,re.M)); out=[]
 for i,m in enumerate(hs):
  e=hs[i+1].start() if i+1<len(hs) else len(t); body=t[m.end():e].strip(); out.append((m.group().lstrip('#').strip(),body))
 return out
def exercise_titles(t,n): return [m.group().strip() for m in re.finditer(r'^#{1,4}.*(?:exercise|challenge|practice|try it|question).*$',t,re.I|re.M)]
